function Assert-RetainedProbeBoolean($Value,[bool]$Expected,[string]$Name){if($Value -isnot [bool] -or $Value -ne $Expected){throw ('Explicit boolean differs: '+$Name)}}
function Assert-RetainedProbeReviewed($Review){
 $names=@(Get-RetainedProbeSources);if($Review.schemaVersion -ne 1 -or $Review.kind -cne 'retained-native-probe-reviewed-sources' -or @($Review.files).Count -ne $names.Count -or @($Review.files.path|Select-Object -Unique).Count -ne $names.Count){throw 'Exact native probe reviewed manifest required.'}
