function Assert-RetainedProbePreparation($Proof){
 if($Proof.schemaVersion -ne 1 -or $Proof.kind -cne 'retained-preparation-host' -or $Proof.status -cne 'retained-pair-prepared-awaiting-raw-proof' -or $Proof.phase -cne 'complete' -or $Proof.runId -cnotmatch '\A[0-9a-f]{32}\z' -or $Proof.observationId -cnotmatch '\A[0-9a-f]{32}\z' -or [string]$Proof.vmId -ine 'eebbfd4e-d964-4aaf-a6e6-5603fb9b6c4c' -or [string]$Proof.baselineId -ine 'eda059b3-6d50-46bb-bdf4-018b99b5b34f' -or $Proof.outcomeCheckpointName -cne ('retained-prepared-'+$Proof.runId) -or [guid]$Proof.outcomeCheckpointId -eq [guid]::Empty){throw 'Completed exact preparation required.'}
 foreach($n in @('sourceExported','shadowExported','pairExported','cleanShutdown','outcomeCheckpointCreated','baselineRestored','memoryRestored')){Assert-RetainedProbeBoolean $Proof.$n $true $n}
 foreach($n in @('commandCompletionUnknown','physicalMappingVerified','cleanRemountVerified','conversionQualified')){Assert-RetainedProbeBoolean $Proof.$n $false $n}
 foreach($n in @('sourceEvidenceSha256','shadowEvidenceSha256','pairEvidenceSha256','reviewedSourcesSha256')){if($Proof.$n -cnotmatch '\A[0-9a-f]{64}\z'){throw 'Preparation pin differs.'}}
 $r=$Proof.retainedInterval;if($r.offset -lt 8GB -or $r.offset -gt (9GB-65536) -or $r.offset%4096 -ne 0 -or $r.length -ne 65536 -or $r.offset -ne ($r.candidateLcn*4096) -or $r.sourceSha256 -cnotmatch '\A[0-9a-f]{64}\z' -or $r.shadowSha256 -cnotmatch '\A[0-9a-f]{64}\z' -or $r.sourceSha256 -ceq $r.shadowSha256){throw 'Prepared retained interval differs.'}
}
function Assert-RetainedProbeCheckpoint($Checkpoint,[string]$Id,[string]$Name){
 if([guid]$Checkpoint.Id -eq [guid]::Empty -or [string]$Checkpoint.Id -ine $Id -or $Checkpoint.Name -cne $Name -or [string]$Checkpoint.VMId -ine 'eebbfd4e-d964-4aaf-a6e6-5603fb9b6c4c' -or $Checkpoint.State -ne 'Off' -or $Checkpoint.MemoryStartup -ne 8GB -or $Checkpoint.DynamicMemoryEnabled){throw 'Exact saved off8GiB checkpoint required.'}
}
function Read-RetainedProbePinned([string]$Path,[string]$Hash,[long]$Maximum=2MB){
 $f=Get-Item -LiteralPath $Path -Force;if($f.PSIsContainer -or ($f.Attributes -band [IO.FileAttributes]::ReparsePoint) -or $f.Length -lt 1 -or $f.Length -gt $Maximum){throw 'Bounded ordinary pinned file required.'}
 $stream=New-Object IO.FileStream($f.FullName,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read)
 try{$sha=[Security.Cryptography.SHA256]::Create();try{$actual=[BitConverter]::ToString($sha.ComputeHash($stream)).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()};if($actual -cne $Hash){throw ('Pinned file differs: '+$f.Name)};$stream.Position=0;$reader=New-Object IO.StreamReader($stream,(New-Object Text.UTF8Encoding($false,$true)),$true,4096,$true);try{$reader.ReadToEnd()|ConvertFrom-Json}finally{$reader.Dispose()}}finally{$stream.Dispose()}
}
function Write-RetainedProbeJson([string]$Path,$Value,[long]$Maximum=2MB){$bytes=(New-Object Text.UTF8Encoding($false,$true)).GetBytes(($Value|ConvertTo-Json -Depth 32));if($bytes.Length -gt $Maximum){throw 'Host JSON exceeds bound.'};$stream=New-Object IO.FileStream($Path,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$stream.Write($bytes,0,$bytes.Length);$stream.Flush($true)}finally{$stream.Dispose()}}
function Import-RetainedProbeFunctions([string]$Path,[string[]]$Names){$tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseFile($Path,[ref]$tokens,[ref]$errors);if($errors.Count){throw 'Reviewed guard source parse failure.'};foreach($name in $Names){$f=@($ast.FindAll({param($n)$n -is [Management.Automation.Language.FunctionDefinitionAst]},$false)|Where-Object Name -CEQ $name);if($f.Count -ne 1){throw ('Named reviewed guard missing: '+$name)};$definition=[regex]::Replace($f[0].Extent.Text,('\Afunction\s+'+[regex]::Escape($name)+'\b'),('function script:'+$name));Invoke-Expression $definition}}
function Copy-RetainedProbePinned([string]$Path,[string]$Destination,[string]$Hash,[long]$Maximum){
 $f=Get-Item -LiteralPath $Path -Force;if($f.PSIsContainer -or ($f.Attributes -band [IO.FileAttributes]::ReparsePoint) -or $f.Length -lt 1 -or $f.Length -gt $Maximum){throw 'Reviewed artifact shape differs.'}
 $stream=New-Object IO.FileStream($f.FullName,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read)
 try{$bytes=New-Object byte[] $stream.Length;$at=0;while($at -lt $bytes.Length){$n=$stream.Read($bytes,$at,$bytes.Length-$at);if($n -eq 0){throw 'Short reviewed artifact.'};$at+=$n};$sha=[Security.Cryptography.SHA256]::Create();try{$actual=[BitConverter]::ToString($sha.ComputeHash($bytes)).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()};if($actual -cne $Hash){throw ('Reviewed artifact hash differs: '+$f.Name)};$out=New-Object IO.FileStream($Destination,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$out.Write($bytes,0,$bytes.Length);$out.Flush($true)}finally{$out.Dispose()};[pscustomobject]@{name=$f.Name;length=$bytes.Length;sha256=$Hash;archive=$Destination}}finally{$stream.Dispose()}
}
function Assert-RetainedProbeArtifacts([object[]]$Files,[string]$Stage){
 if($Stage -cnotin @('attachment','inspection','native') -or $Files.Count -lt 1 -or @($Files.name|Select-Object -Unique).Count -ne $Files.Count){throw 'Artifact stage/count differs.'}
 $maxCount=switch($Stage){attachment{1}inspection{194}native{9}};$sum=0L
 if($Files.Count -gt $maxCount){throw 'Too many probe artifacts.'}
 foreach($f in $Files){$maximum=0L;$empty=$false
  switch($Stage){attachment{if($f.name -ceq 'attachment.json'){$maximum=1MB}}inspection{if($f.name -ceq 'pair.json'){$maximum=2MB}elseif($f.name -ceq 'started.json'){$maximum=16KB}elseif($f.name -cmatch '\Aquery-[0-9]{3}\.bin\z'){$maximum=2MB;$empty=$true}}native{switch -CaseSensitive($f.name){'lab-native-probe.exe'{$maximum=16MB}'request.json'{$maximum=16KB}'probe.json'{$maximum=1MB}'probe.intent.json'{$maximum=1MB}'process-intent.json'{$maximum=64KB}'process-started.json'{$maximum=64KB}'process-result.json'{$maximum=64KB}'probe.stdout'{$maximum=64KB;$empty=$true}'probe.stderr'{$maximum=64KB;$empty=$true}}}}
  if($maximum -eq 0 -or $f.length -lt 0 -or (-not $empty -and $f.length -eq 0) -or $f.length -gt $maximum -or $f.sha256 -cnotmatch '\A[0-9a-f]{64}\z' -or ([IO.FileAttributes]$f.attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'Artifact allowlist/type/hash/size differs.'};$sum+=$f.length
 }
 $limit=switch($Stage){attachment{1MB}inspection{19MB}native{19MB}};if($sum -gt $limit){throw 'Probe artifact aggregate exceeds bound.'}
}
