 if(@($inspection.nativeSources).Count -ne 2){throw 'Inspection native source coverage differs.'};foreach($nativePin in $inspection.nativeSources){$expected=@($priorSources|Where-Object name -CEQ $nativePin.name);if($nativePin.name -cnotin @('NativeRetainedFixture.cs','NativeRetainedFixture.Windows.cs') -or $expected.Count -ne 1 -or $nativePin.sha256 -cne $expected[0].sha256 -or $nativePin.length -ne $expected[0].length){throw 'Inspection native helper provenance differs.'}}
 if(@($inspection.native.queries).Count -ne @($inspection.artifacts).Count -or @($inspectionExport.files).Count -ne (@($inspection.artifacts).Count+2) -or @($inspection.native.queries|Where-Object code -In @(0x90074,0x9c280)).Count){throw 'Inspection native query coverage/mutation differs.'}
 foreach($a in $inspection.artifacts){$f=@($inspectionExport.files|Where-Object name -CEQ $a.name);$q=@($inspection.native.queries|Where-Object artifact -CEQ $a.name);if($f.Count -ne 1 -or $q.Count -ne 1 -or $f[0].sha256 -cne $a.sha256 -or $q[0].sha256 -cne $a.sha256 -or $f[0].length -ne $a.length -or $q[0].bytesReturned -ne $a.length){throw 'Inspection native buffer binding differs.'};Assert-RetainedQueryOutcome $q[0]}
 $record.inspectionExported=$true;$inspectionSha=($inspectionExport.files|Where-Object name -CEQ 'pair.json').sha256;$record['inspectionEvidenceSha256']=$inspectionSha
 $request=New-RetainedProbeRequest $source $shadow $inspection $inspectionSha;Assert-NativeProbeRequest $request $runId
 if($request.retained_offset -ne $prepared.retainedInterval.offset -or $request.source_retained_sha256 -cne $prepared.retainedInterval.sourceSha256 -or $request.shadow_retained_sha256 -cne $prepared.retainedInterval.shadowSha256){throw 'Request differs from prepared retained interval.'}
 $requestPath=Join-Path $outputRoot 'request.json';Write-RetainedProbeJson $requestPath $request 16KB;$requestSha=(Get-FileHash -LiteralPath $requestPath -Algorithm SHA256).Hash.ToLowerInvariant();$record['requestSha256']=$requestSha
 $script:phase='native-isolation';Save-RetainedProbeProgress;$first=Invoke-RetainedProbePhase $firstProbe $false first-native;$record.firstNativeExported=$true;$record['firstNativeReportSha256']=$first.sha256
 $script:phase='clean-shutdown-isolated';Save-RetainedProbeProgress;Stop-RetainedProbeGuest $prepared.outcomeCheckpointId
 $isolated=New-RetainedProbeCheckpoint ('retained-isolated-'+$firstProbe) $prepared.outcomeCheckpointId;$record.isolatedCheckpointId=[string]$isolated.Id;$record['isolatedCheckpointName']=$isolated.Name
 $script:phase='restart-isolated';Save-RetainedProbeProgress;Assert-RetainedProbeCurrent ([string]$isolated.Id) 8GB|Out-Null;Invoke-LabAction -Action Start -Lane win11 -Confirm:$false|Out-Null
 $script:session=Open-RetainedProbeSession;$policy=Initialize-LabGuestSession -Session $session;if($policy.status -cne 'ready'){throw 'Restarted session policy refused.'};Write-RetainedProbeJson (Join-Path $outputRoot 'second-session.json') $policy 64KB;Copy-RetainedProbeGuestSources
 $script:phase='reattach-excluded';Save-RetainedProbeProgress;$attachment=Restore-RetainedProbeShadow Excluded attachment-excluded;$record['excludedAttachmentSha256']=($attachment.files|Where-Object name -CEQ 'attachment.json').sha256
