 if($first.report.target_retained_sha256 -cne $second.report.target_retained_sha256 -or $first.report.shadow_retained_sha256 -cne $second.report.shadow_retained_sha256){throw 'Retained raw hashes changed across restart.'}
 $record['targetPartitionSha256']=$second.report.target_partition_sha256;$record['shadowPartitionSha256']=$second.report.shadow_partition_sha256
